import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

export class InputError extends Error {
  constructor(message) {
    super(message);
    this.name = 'InputError';
  }
}

function requiredText(value, label, limit) {
  if (typeof value !== 'string' || !value.trim()) {
    throw new InputError(`${label} is required.`);
  }
  const text = value.trim();
  if (text.length > limit) throw new InputError(`${label} must be ${limit} characters or fewer.`);
  return text;
}

export function createBookStore(filePath) {
  let pending = Promise.resolve();

  async function readBooks() {
    try {
      const books = JSON.parse(await readFile(filePath, 'utf8'));
      if (!Array.isArray(books)) throw new Error('Book data must be a JSON array.');
      return books;
    } catch (error) {
      if (error.code === 'ENOENT') return [];
      throw error;
    }
  }

  async function saveBooks(books) {
    await mkdir(dirname(filePath), { recursive: true });
    const temporaryPath = `${filePath}.${randomUUID()}.tmp`;
    await writeFile(temporaryPath, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
    await rename(temporaryPath, filePath);
  }

  function mutate(change) {
    const operation = pending.then(async () => {
      const books = await readBooks();
      const result = change(books);
      await saveBooks(books);
      return result;
    });
    pending = operation.catch(() => {});
    return operation;
  }

  return {
    async all() {
      await pending;
      return readBooks();
    },
    async get(id) {
      await pending;
      return (await readBooks()).find((book) => book.id === id) ?? null;
    },
    add(input) {
      const title = requiredText(input?.title, 'Title', 160);
      const author = requiredText(input?.author, 'Author', 120);
      const notes = input?.notes ?? '';
      if (typeof notes !== 'string' || notes.length > 5000) {
        throw new InputError('Notes must be 5,000 characters or fewer.');
      }
      return mutate((books) => {
        const book = {
          id: randomUUID(),
          title,
          author,
          notes: notes.trim(),
          status: 'reading',
          createdAt: new Date().toISOString(),
          finishedAt: null
        };
        books.unshift(book);
        return book;
      });
    },
    setStatus(id, status) {
      if (status !== 'reading' && status !== 'finished') {
        throw new InputError('Status must be reading or finished.');
      }
      return mutate((books) => {
        const book = books.find((item) => item.id === id);
        if (!book) return null;
        book.status = status;
        book.finishedAt = status === 'finished' ? (book.finishedAt ?? new Date().toISOString()) : null;
        return book;
      });
    },
    remove(id) {
      return mutate((books) => {
        const index = books.findIndex((book) => book.id === id);
        if (index === -1) return false;
        books.splice(index, 1);
        return true;
      });
    }
  };
}

