import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { createBookStore, InputError } from './library.mjs';

const root = dirname(fileURLToPath(import.meta.url));
const staticFiles = new Map([
  ['/styles.css', ['styles.css', 'text/css; charset=utf-8']],
  ['/app.js', ['app.js', 'text/javascript; charset=utf-8']]
]);

function json(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(data));
}

async function readBody(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 1_000_000) throw new InputError('Request is too large.');
  }
  try {
    return JSON.parse(body);
  } catch {
    throw new InputError('Invalid JSON.');
  }
}

export function createAppServer({ dataFile = join(root, 'data', 'books.json'), publicDir = join(root, 'public') } = {}) {
  const store = createBookStore(dataFile);

  return createServer(async (req, res) => {
    try {
      const path = new URL(req.url, 'http://localhost').pathname;
      if (path === '/api/books') {
        if (req.method === 'GET') return json(res, 200, await store.all());
        if (req.method === 'POST') return json(res, 201, await store.add(await readBody(req)));
      }

      const bookPath = path.match(/^\/api\/books\/([0-9a-f-]+)$/i);
      if (bookPath) {
        const id = bookPath[1];
        if (req.method === 'GET') {
          const book = await store.get(id);
          return json(res, book ? 200 : 404, book ?? { error: 'Book not found.' });
        }
        if (req.method === 'PATCH') {
          const book = await store.setStatus(id, (await readBody(req))?.status);
          return json(res, book ? 200 : 404, book ?? { error: 'Book not found.' });
        }
        if (req.method === 'DELETE') {
          const removed = await store.remove(id);
          return json(res, removed ? 200 : 404, removed ? { ok: true } : { error: 'Book not found.' });
        }
      }

      if (path === '/' || /^\/books\/[0-9a-f-]+$/i.test(path)) {
        if (req.method !== 'GET') return json(res, 405, { error: 'Method not allowed.' });
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        return res.end(await readFile(join(publicDir, 'index.html')));
      }
      if (staticFiles.has(path)) {
        if (req.method !== 'GET') return json(res, 405, { error: 'Method not allowed.' });
        const [file, type] = staticFiles.get(path);
        res.writeHead(200, { 'Content-Type': type });
        return res.end(await readFile(join(publicDir, file)));
      }
      json(res, 404, { error: 'Not found.' });
    } catch (error) {
      if (!(error instanceof InputError)) console.error(error);
      if (!res.headersSent) json(res, error instanceof InputError ? 400 : 500, { error: error instanceof InputError ? error.message : 'Something went wrong.' });
      else res.end();
    }
  });
}

if (process.argv[1] && fileURLToPath(import.meta.url) === fileURLToPath(new URL(`file://${process.argv[1]}`))) {
  const port = Number(process.env.PORT) || 3000;
  createAppServer().listen(port, () => console.log(`Reading journal running at http://localhost:${port}`));
}

