const app = document.querySelector('#app');
const dialog = document.querySelector('#book-dialog');
const form = document.querySelector('#book-form');
const toast = document.querySelector('#toast');
let toastTimer;

const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
})[character]);

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Something went wrong.');
  return data;
}

function notify(message) {
  toast.textContent = message;
  toast.classList.add('visible');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('visible'), 3200);
}

function cover(book, large = false) {
  const palette = [...book.title].reduce((total, char) => total + char.charCodeAt(0), 0) % 5;
  return `<div class="book-cover palette-${palette}${large ? ' cover-large' : ''}" aria-hidden="true">
    <div class="cover-inner"><span class="cover-top">MARGIN · LIBRARY</span><span class="cover-decoration">✳</span><span class="cover-title">${escapeHtml(book.title)}</span><span class="cover-author">${escapeHtml(book.author)}</span></div>
  </div>`;
}

function bookCard(book) {
  const finished = book.status === 'finished';
  return `<article class="book-card">
    <a class="card-cover-link" href="/books/${book.id}" aria-label="View ${escapeHtml(book.title)}">${cover(book)}</a>
    <div class="card-info">
      <span class="card-kicker">${finished ? 'FINISHED BOOK' : 'ON YOUR NIGHTSTAND'}</span>
      <a class="card-title" href="/books/${book.id}">${escapeHtml(book.title)}</a>
      <p class="card-author">by ${escapeHtml(book.author)}</p>
      <p class="card-notes">${book.notes ? escapeHtml(book.notes) : 'No notes yet — just the start of a story.'}</p>
      <div class="card-bottom">
        <span class="status-label ${finished ? 'is-finished' : ''}"><span class="status-dot"></span>${finished ? 'Finished' : 'Reading'}</span>
        ${finished ? `<a class="text-action" href="/books/${book.id}">View book <span aria-hidden="true">↗</span></a>` : `<button class="text-action" type="button" data-finish="${book.id}">Mark finished <span aria-hidden="true">↗</span></button>`}
      </div>
    </div>
  </article>`;
}

function emptyShelf(kind) {
  const reading = kind === 'reading';
  return `<div class="empty-shelf ${reading ? '' : 'empty-finished'}">
    <div class="empty-illustration" aria-hidden="true"><div class="empty-book empty-book-back"></div><div class="empty-book empty-book-front"><span>✳</span></div><div class="empty-spark">✦</div></div>
    <div class="empty-copy"><span class="eyebrow">${reading ? 'A BLANK PAGE' : 'THE STORY CONTINUES'}</span><h3>${reading ? 'A good book belongs here.' : 'Your finished shelf is waiting.'}</h3><p>${reading ? 'Add what you’re reading, and let this little shelf fill up one story at a time.' : 'When you finish a book, mark it as finished and you’ll find it right here.'}</p>${reading ? '<button type="button" class="inline-link" data-open-form>Add your first book <span aria-hidden="true">↗</span></button>' : ''}</div>
  </div>`;
}

function section(id, title, subtitle, books) {
  return `<section class="shelf-section" id="${id}">
    <div class="section-heading"><div><div class="section-eyebrow"><span class="section-line"></span> ${id === 'reading' ? 'THE HERE & NOW' : 'THE BOOKS THAT STAY'}</div><h2>${title}<span class="accent-dot">.</span></h2><p>${subtitle}</p></div><span class="section-count">${String(books.length).padStart(2, '0')} ${books.length === 1 ? 'BOOK' : 'BOOKS'}</span></div>
    ${books.length ? `<div class="book-grid">${books.map(bookCard).join('')}</div>` : emptyShelf(id)}
  </section>`;
}

function renderDashboard(books) {
  document.title = 'My library — Margin';
  document.querySelector('#page-label').textContent = 'OVERVIEW';
  document.querySelector('#nav-library').classList.add('active');
  const reading = books.filter((book) => book.status === 'reading');
  const finished = books.filter((book) => book.status === 'finished');
  app.innerHTML = `<div class="dashboard">
    <section class="hero">
      <div class="hero-copy"><p class="hero-eyebrow"><span class="hero-star">✳</span> YOUR READING JOURNAL</p><h1>Stories worth<br><em>keeping close.</em></h1><p class="hero-description">A quiet little corner for the books you’re reading, the ones you’ve loved, and all the thoughts in between.</p><button type="button" class="hero-button" data-open-form>Add a book <span aria-hidden="true">↗</span></button><p class="hero-small">ONE BOOK AT A TIME, ONE PAGE AT A TIME.</p></div>
      <div class="hero-art" aria-hidden="true"><div class="hero-art-circle"></div><div class="hero-art-leaf leaf-one"></div><div class="hero-art-leaf leaf-two"></div><div class="hero-art-leaf leaf-three"></div><div class="art-book art-book-back"><div></div></div><div class="art-book art-book-front"><div class="art-book-content"><span>MARGIN<br>READING CLUB</span><span class="art-book-sun">✳</span><strong>one more<br>chapter.</strong><span>EST. EVERY DAY</span></div></div><span class="art-caption">A PLACE FOR YOUR PAGES ↗</span></div>
    </section>
    <div class="library-summary"><div><span class="summary-symbol">✳</span><span>YOUR LIBRARY, AT A GLANCE</span></div><p><strong>${String(reading.length).padStart(2, '0')}</strong> in progress <span class="summary-divider">/</span> <strong>${String(finished.length).padStart(2, '0')}</strong> finished</p></div>
    ${section('reading', 'Currently reading', 'The stories keeping you company right now.', reading)}
    ${section('finished', 'Finished books', 'The ones you’ll carry with you.', finished)}
  </div>`;
  if (location.hash) requestAnimationFrame(() => document.querySelector(location.hash)?.scrollIntoView());
}

function renderDetail(book) {
  document.title = `${book.title} — Margin`;
  document.querySelector('#page-label').textContent = 'BOOK DETAILS';
  document.querySelector('#nav-library').classList.remove('active');
  const finished = book.status === 'finished';
  app.innerHTML = `<div class="detail-page">
    <a href="/" class="back-link"><span aria-hidden="true">←</span> Back to my library</a>
    <div class="detail-layout"><div class="detail-visual"><div class="detail-visual-inner">${cover(book, true)}<p>EVERY BOOK HAS A STORY TO TELL.</p></div></div>
      <div class="detail-content"><div class="detail-topline"><span class="eyebrow">FROM YOUR LIBRARY</span><span class="status-label ${finished ? 'is-finished' : ''}"><span class="status-dot"></span>${finished ? 'Finished' : 'Currently reading'}</span></div>
        <h1>${escapeHtml(book.title)}<span class="accent-dot">.</span></h1><p class="detail-author">by <strong>${escapeHtml(book.author)}</strong></p>
        <div class="detail-rule"></div>
        <div class="notes-heading"><span class="notes-icon">✳</span><div><span class="eyebrow">IN THE MARGINS</span><h2>Your notes</h2></div></div>
