        <div class="detail-actions"><button type="button" class="button-primary" data-status="${finished ? 'reading' : 'finished'}" data-id="${book.id}">${finished ? 'Move back to reading' : 'Mark as finished'} <span aria-hidden="true">↗</span></button><button type="button" class="button-outline" data-share="${book.id}">Copy book link <span aria-hidden="true">↗</span></button></div>
        <button class="delete-link" type="button" data-delete="${book.id}">Remove from library</button>
      </div>
    </div>
    <div class="detail-bottom"><span>✳</span> THE BEST STORIES STAY WITH US.</div>
  </div>`;
}

async function load() {
  try {
    const id = location.pathname.match(/^\/books\/([0-9a-f-]+)$/i)?.[1];
    if (id) {
      const book = await request(`/api/books/${id}`);
      renderDetail(book);
    } else {
      const books = await request('/api/books');
      renderDashboard(books);
    }
  } catch (error) {
    app.innerHTML = `<div class="error-page"><span class="eyebrow">A LITTLE DETOUR</span><h1>We couldn’t find that page<span class="accent-dot">.</span></h1><p>${escapeHtml(error.message)}</p><a class="button-primary" href="/">Back to library <span aria-hidden="true">↗</span></a></div>`;
  }
}

function openForm() {
  document.querySelector('#form-error').hidden = true;
  dialog.showModal();
  document.querySelector('#book-title').focus();
}

document.addEventListener('click', async (event) => {
  if (event.target.closest('[data-open-form]')) return openForm();
  if (event.target.closest('[data-close-form]')) return dialog.close();
  const finish = event.target.closest('[data-finish]');
  const status = event.target.closest('[data-status]');
  const share = event.target.closest('[data-share]');
  const remove = event.target.closest('[data-delete]');
  try {
    if (finish || status) {
      const id = finish?.dataset.finish ?? status.dataset.id;
      const nextStatus = finish ? 'finished' : status.dataset.status;
      await request(`/api/books/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: nextStatus }) });
      await load();
      notify(nextStatus === 'finished' ? 'Moved to your finished shelf.' : 'Moved back to currently reading.');
    } else if (share) {
      const url = new URL(`/books/${share.dataset.share}`, location.origin).href;
      if (navigator.clipboard?.writeText) {
        try { await navigator.clipboard.writeText(url); notify('Book link copied to clipboard.'); }
        catch { window.prompt('Copy this book link:', url); }
      } else window.prompt('Copy this book link:', url);
    } else if (remove && window.confirm('Remove this book from your library? This cannot be undone.')) {
      await request(`/api/books/${remove.dataset.delete}`, { method: 'DELETE' });
      location.href = '/';
    }
  } catch (error) { notify(error.message); }
});

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  const submit = form.querySelector('[type="submit"]');
  const errorElement = document.querySelector('#form-error');
  submit.disabled = true;
  errorElement.hidden = true;
  try {
    const data = Object.fromEntries(new FormData(form));
    await request('/api/books', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
    dialog.close();
    form.reset();
    if (location.pathname !== '/') location.href = '/';
    else { await load(); notify('A new story has joined your shelf.'); }
  } catch (error) {
    errorElement.textContent = error.message;
    errorElement.hidden = false;
  } finally { submit.disabled = false; }
});

dialog.addEventListener('click', (event) => { if (event.target === dialog) dialog.close(); });
load();

